package main

// Messages are read from the runtime: hidden whole while it is down
// (runtimeGroup, R19b render check).
var messageActivitySection = runtimeGroup(oaGroup("messages", "Messages", "Text from other apps is untrusted. Open a message to read its retained text.",
	oaStatus("messages-status"),
	`<div id="message-events"></div><button id="messages-more" type="button" hidden>Show more messages</button><section id="message-reader" hidden><button id="message-close" type="button" data-status="messages-status">Close message</button><h3 id="message-headline"></h3><pre id="message-body"></pre></section>`))

const messageActivityScript = `
const messageEvents=new Map();let messageCursor='',messageAtEnd=false,messageBusy=false,messageRead=false,messageFailed=false,messageToken=0,messageExpiryTimer=null;
function clearMessageBody(){messageToken++;if(messageExpiryTimer!==null)clearTimeout(messageExpiryTimer);messageExpiryTimer=null;el('message-headline').textContent='';el('message-body').textContent='';el('message-reader').hidden=true}
async function openActivityMessage(id){clearMessageBody();const token=messageToken;
 try{const r=await call('/activity/message?id='+encodeURIComponent(id));if(token!==messageToken||document.hidden)return;if(r.outcome!=='page'){oaSetStatus('messages-status','ok',r.outcome==='forbidden'?'Access to this message was refused.':'The message text is unavailable.');return}if(r.id!==id||r.expiresAt<=Date.now()){oaSetStatus('messages-status','ok','The message text is no longer retained.');return}
 el('message-headline').textContent=r.headline||'';el('message-body').textContent=r.body||'';el('message-reader').hidden=false;
 messageExpiryTimer=setTimeout(()=>{clearMessageBody();renderMessageActivity();oaSetStatus('messages-status','ok','The message text expired.');},r.expiresAt-Date.now());
 }catch(e){if(token===messageToken){clearMessageBody();oaShowError('messages-status',e.message||String(e))}}}
function messageDeliveryText(e){if(!e.deliveryState)return '';const reasons={expired:'Not delivered: message expired',refused:'Not delivered: permission refused',context_closed:'Not delivered: conversation closed',receiver_removed:'Not delivered: receiver removed',peer_removed:'Not delivered: paired computer removed',lost:'Delivery evidence was lost',unconfirmed:'Delivery was not confirmed'};const state=e.deliveryState==='delivered'?'Delivered to the inbox; processing unconfirmed':reasons[e.undeliveredReason]||('Not delivered: '+String(e.undeliveredReason||'reason unavailable').replace(/_/g,' '));return ' · '+state+(e.deliveryAt>0?' · '+'recorded '+new Date(e.deliveryAt).toLocaleString():'')}
function renderMessageActivity(){const out=el('message-events');out.replaceChildren();
 for(const e of [...messageEvents.values()].sort((a,b)=>b.at-a.at)){const row=document.createElement('div');row.className='oa-row';const peer=document.createElement('span');peer.setAttribute('data-evidence','claimed');peer.textContent='“'+e.from+'” · '+(e.fromChat||'Unnamed chat')+' → “'+e.to+'” · '+(e.toChat||'Unnamed chat');const text=document.createElement('span');const expired=e.expiresAt<=Date.now();
 const starting=String(e.outcome).startsWith('receiver_start_');const starts={started:'Starting…',ready:'Receiver inbox ready',pending:'Receiver start pending',unknown:'Receiver start outcome unknown',refused:'Receiver start refused',stopped:'Stopped by you',hop_limit:'Not started: too many assistants in a row woke each other'};const outcome=starting?(starts[String(e.outcome).slice(15)]||'Receiver start '+String(e.outcome).slice(15).replace(/_/g,' ')):e.outcome==='completed'?'answered'+(e.updatedAt>e.at?' after '+Math.floor((e.updatedAt-e.at)/60000)+' min':''):e.outcome==='sent'?'accepted':String(e.outcome).replace(/_/g,' ');const delivered={copy:' · answered in a copy of this conversation',read_only:' · Codex answered read-only because the Codex app was closed',desktop_queue:' · queued into the running Codex app, which runs this turn itself; OA cannot stop it',resumed:' · answered in this conversation while Claude was closed'}[e.delivery]||'';text.textContent=(starting?outcome+(e.folder?' · conversation in “'+e.folder+'”':'')+delivered:e.kind+' · '+outcome+(e.metadataOnly?' · delivery metadata':expired?' · message text expired':' · proved at the native image'))+messageDeliveryText(e)+(e.origin?' · asked by a turn another assistant woke':'');row.append(peer,text);if(e.technical&&Object.keys(e.technical).length){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Technical details';const data=document.createElement('pre');data.textContent=JSON.stringify(e.technical||{},null,2);details.append(summary,data);row.append(details);}
 if(!expired&&!starting&&!e.metadataOnly){const button=document.createElement('button');button.type='button';button.textContent='Open message';button.onclick=()=>openActivityMessage(e.id);row.append(button)}
 const state=String(e.outcome).slice(15);if(starting&&!expired&&e.delivery!=='desktop_queue'&&(state==='started'||state==='ready'||state==='unknown')){const halt=document.createElement('button');halt.type='button';halt.textContent='Stop this turn';halt.onclick=()=>stopWokenTurn(e,halt);row.append(halt)}
 if(starting&&e.revoke){const stop=document.createElement('button');stop.type='button';stop.textContent='Stop waking conversations';stop.onclick=()=>stopMessageDirection(e,stop);row.append(stop)}out.append(row)}
 el('messages-more').hidden=messageAtEnd;}
async function stopWokenTurn(e,button){button.disabled=true;try{const r=await call('/activity/message/stop?id='+encodeURIComponent(e.id),{});oaSetStatus('messages-status','ok',r.outcome==='page'?'This turn stops within two seconds; “'+e.from+'” can still wake “'+e.to+'” conversations.':'Nothing was running to stop.')}catch(x){oaShowError('messages-status',x.message||String(x))}finally{button.disabled=false}}
async function stopMessageDirection(e,button){button.disabled=true;try{const page=await call('/rights?cursor=');if(page.Outcome!=='page'||typeof page.Revision!=='string'||!page.Revision){oaSetStatus('messages-status','ok','The current permissions could not be read; nothing was stopped.');return}
 const r=await call('/rights',{edit:'revoke',revision:page.Revision,account:e.revoke.account,program:e.revoke.program,action:e.revoke.action,resource:e.revoke.resource});oaSetStatus('messages-status','ok',r.Outcome==='applied'?'“'+e.from+'” can no longer wake “'+e.to+'” conversations; its next request asks you again.':'Nothing was stopped; the permissions changed or are unavailable.')}catch(x){oaShowError('messages-status',x.message||String(x))}finally{button.disabled=false}}
function keepMessageActivity(e){const old=messageEvents.get(e.id);if(!old){messageEvents.set(e.id,e);return}const newer=(e.version||0)>(old.version||0)||(e.version||0)===(old.version||0)&&(e.updatedAt||0)>=(old.updatedAt||0);const next={...(newer?e:old)};const delivery=e.deliveryState&&(e.deliveryAt||0)>=(old.deliveryAt||0)?e:old;if(delivery.deliveryState){next.deliveryState=delivery.deliveryState;next.undeliveredReason=delivery.undeliveredReason;next.deliveryAt=delivery.deliveryAt;next.technical={...next.technical,delivery_state:delivery.deliveryState,undelivered_reason:delivery.undeliveredReason||'',delivery_at:String(delivery.deliveryAt||0)}}messageEvents.set(e.id,next)}
async function readMessageActivity(more=false){if(messageBusy||document.hidden)return;messageBusy=true;
 try{let problem=false,cursor=messageCursor;for(let n=0;n<8;n++){const p=await call('/activity/messages?cursor='+encodeURIComponent(cursor));if(p.outcome==='gap'){problem=true;messageFailed=true;messageAtEnd=true;messageEvents.clear();messageCursor='';clearMessageBody();oaSetStatus('messages-status','ok','Message history changed; it reads again shortly.');break}
 if(p.outcome!=='page'){problem=true;messageFailed=true;messageEvents.clear();messageCursor='';clearMessageBody();messageAtEnd=true;oaSetStatus('messages-status','ok','Message history is '+String(p.outcome||'unavailable').replace(/_/g,' ')+'.');break}
 for(const e of p.events||[])keepMessageActivity(e);while(messageEvents.size>2000)messageEvents.delete(messageEvents.keys().next().value);messageCursor=p.next||'';messageAtEnd=!!p.atEnd||!messageCursor;if(messageAtEnd||!messageCursor)break;cursor=messageCursor;}
 if(!problem){if(!messageRead||messageFailed)oaSetStatus('messages-status','ok','');messageRead=true;messageFailed=false;}renderMessageActivity();}catch(e){messageFailed=true;messageEvents.clear();messageCursor='';messageAtEnd=true;clearMessageBody();renderMessageActivity();oaShowError('messages-status',e.message||String(e))}finally{messageBusy=false}}
el('message-close').onclick=()=>{clearMessageBody();oaSetStatus('messages-status','ok','Message closed.')};el('messages-more').onclick=()=>readMessageActivity(true);
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearMessageBody()});window.addEventListener('pagehide',clearMessageBody);
`
